let encrypt (str:string) (n:int) =
    if System.String.IsNullOrEmpty(str) then str
    let rec loop s n =
        if n <= 0 then s
        else
            let even = s |> Seq.mapi (fun i c -> if i % 2 = 0 then Some c else None) |> Seq.choose id |> Seq.toArray
            let odd = s |> Seq.mapi (fun i c -> if i % 2 <> 0 then Some c else None) |> Seq.choose id |> Seq.toArray
            let newStr = System.String.Concat(odd) + System.String.Concat(even)
            loop newStr (n - 1)
    loop str n

let decrypt (str:string) (n:int) =
    if System.String.IsNullOrEmpty(str) then str
    if n <= 0 then str
    let len = str.Length
    let half = len / 2
    let rec loop s n =
        if n <= 0 then s
        else
            let even = s.Substring(half)
            let odd = s.Substring(0, half)
            let newStr = 
                [| for i in 0 .. half - 1 do
                    yield even.[i]
                    yield odd.[i] |]
            if len % 2 <> 0 then newStr.[len - 1] <- even.[half - 1]
            loop (System.String.Concat(newStr)) (n - 1)
    loop str n
